function migrateDecoder(){if(state.decoderVersion!==2){for(const [id,c]of Object.entries(state.coverage)){if(id!=='solana'){c.inspected=[];c.inspectionErrors=Object.fromEntries([...new Set(state.records.filter(r=>r.chain===id).map(r=>r.hash))].map(h=>[h,'需更新旧版返佣解析']));c.status='stale'}}state.decoderVersion=2}}
