const selectedValues=id=>[...$(id).selectedOptions].map(o=>o.value).filter(v=>v!=='all');
function drawFilterMenus(){for(const menu of document.querySelectorAll('[data-filter]')){const select=$(menu.dataset.filter),options=[...select.options].filter(o=>o.value!=='all'),body=menu.querySelector('.checkmenu'),signature=JSON.stringify(options.map(o=>[o.value,o.text]));if(body.dataset.signature!==signature){body.innerHTML=options.map(o=>`<label><input type="checkbox" value="${esc(o.value)}"><span>${esc(o.text)}</span></label>`).join('');body.dataset.signature=signature}const chosen=new Set(selectedValues(select.id));for(const input of body.querySelectorAll('input')){input.checked=chosen.has(input.value);input.disabled=select.disabled}menu.querySelector('.filtercount').textContent=chosen.size||'';menu.classList.toggle('has-selection',chosen.size>0);menu.hidden=view==='coverage'||view==='review'&&select.id==='statusFilter'}}
for(const menu of document.querySelectorAll('[data-filter]')){menu.addEventListener('change',e=>{if(e.target.type!=='checkbox')return;const select=$(menu.dataset.filter);for(const option of select.options)if(option.value===e.target.value)option.selected=e.target.checked;page=1;render()});menu.addEventListener('toggle',()=>{if(menu.open)for(const other of document.querySelectorAll('[data-filter]'))if(other!==menu)other.open=false})}
document.addEventListener('click',e=>{for(const menu of document.querySelectorAll('[data-filter]'))if(!menu.contains(e.target))menu.open=false});document.addEventListener('keydown',e=>{if(e.key==='Escape')for(const menu of document.querySelectorAll('[data-filter]')){if(menu.open){menu.open=false;menu.querySelector('summary').focus()}}});
const allows=(id,value)=>!selectedValues(id).length||selectedValues(id).includes(value);
const valued=()=>valueGroups(summarize(autoAccount(state.records)),prices,preferences);
const visibleGroups=groups=>filterMinimum(groups.filter(matches).filter(statusMatches),$('minimumUsd').value,$('minimumField').value);
const usd=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:4})+' U';
async function refreshPrices(){if(priceBusy)return;priceBusy=true;$('priceStatus').textContent='报价更新中';const assets=[...new Map(summarize(autoAccount(state.records)).map(g=>[g.chain+':'+g.asset,{chain:g.chain,asset:g.asset}])).values()];let failed=false;try{for(let i=0;i<assets.length;i+=30){const batch=assets.slice(i,i+30);let data=await lookupPrices(batch);Object.assign(prices,data.prices);if(data.errors?.length){const missing=batch.filter(a=>!data.prices[a.chain+':'+a.asset]);if(missing.length){const r=await fetch('/api/prices',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({assets:missing})});if(r.ok){const fallback=await r.json();Object.assign(prices,fallback.prices);failed ||= !!fallback.errors?.length}else failed=true}}}}catch{failed=true}finally{priceBusy=false;$('priceStatus').textContent=(failed?'部分缺价 · ':'')+'报价 '+new Date().toLocaleTimeString('zh-CN');render()}}
function save(){try{localStorage.setItem(walletStorage(),JSON.stringify(state));localStorage.setItem('rebate-wallets-v1',JSON.stringify({evm:EVM,sol:SOL}));localStorage.setItem('rebate-ledger-v1',JSON.stringify(state))}catch{storageWarn='浏览器存储不足或不可用，请立即导出备份，避免刷新丢失数据。'}}
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',6000)}
const statusText={unpaid:'未返还',partial:'返还不足',settled:'已返足够',over:'返还超额'};
function badge(s){return `<span class="pill ${s==='over'?'red':s==='settled'?'':'amber'}">${statusText[s]||esc(s)}</span>`}
function link(r){const c=chainBy(r.chain);return c.explorer?`${c.explorer.replace(/\/$/,'')}/${r.chain==='196'?'tx/':'tx/'}${encodeURIComponent(r.hash)}`:''}
function matches(r){const q=$('search').value.trim().toLowerCase();return allows('chainFilter',r.chain)&&allows('tokenFilter',r.chain+':'+r.asset)&&allows('assetFilter',r.asset==='native'?'native':'token')&&(!q||[r.trader,r.from,r.to,r.hash,r.symbol,r.asset].some(s=>s?.toLowerCase().includes(q)))}
function statusMatches(g){const vs=selectedValues('statusFilter');return !vs.length||vs.includes(g.status)||vs.includes('outstanding')&&['unpaid','partial'].includes(g.status)}
function complete(id){return state.coverage[id]?.status==='complete'}
function render(){$('evmDisplay').textContent=EVM||'尚未设置';$('solDisplay').textContent=SOL||'尚未设置';let groups;try{groups=valued()}catch(e){toast(e.message);groups=[]}const pending=pendingReview(state.records),done=required.filter(complete).length;$('reviewCount').textContent=pending.length;$('minimumUsd').closest('label').hidden=$('minimumField').hidden=view==='review';const tokenSelection=selectedValues('tokenFilter');const tokenOptions=new Map(state.records.filter(r=>r.kind!=='ignore').map(r=>[r.chain+':'+r.asset,r]));$('tokenFilter').innerHTML='<option value="all">全部币种 / 合约</option>'+[...tokenOptions].sort((a,b)=>a[1].symbol.localeCompare(b[1].symbol)).map(([k,r])=>`<option value="${esc(k)}">${esc(r.symbol)} · ${esc(chainBy(r.chain).name)} · ${r.asset==='native'?'原生':short(r.asset)}</option>`).join('');for(const o of $('tokenFilter').options)o.selected=tokenSelection.includes(o.value);drawFilterMenus();const counts={unpaid:0,partial:0,settled:0,over:0};groups.forEach(g=>counts[g.status]++);$('metrics').innerHTML=[['待返还',counts.unpaid+counts.partial,'按地址 × 网络 × 币种计数'],['已返足够',counts.settled,'按自动归属记录核算'],['返还超额',counts.over,'超额不跨链、不跨币抵扣'],['已扫描网络',`${done}<small> / ${required.length}</small>`,'已查完的指定网络']].map(([label,note,sub])=>`<article><p>${label}</p><strong>${note}</strong></article>`).join('');$('updated').textContent=state.updated?'更新 '+new Date(state.updated).toLocaleString('zh-CN'):'尚未同步';$('notice').innerHTML=busy?`<div class="progressline"></div>${esc(progress)}`:esc(storageWarn||(done<required.length?`历史扫描 ${done}/${required.length} · 账目持续更新`:(pending.length?'历史扫描完成 · '+pending.length+' 笔待核对':'历史扫描完成')));$('syncButton').textContent=busy?'暂停同步':'同步历史 ↻';$('setupButton').disabled=$('retryButton').disabled=busy;let rows=[],headers=[];
if(view==='ledger'){
const displayed=visibleGroups(groups),addresses=byAddress(displayed),totals=addressTotals(displayed);
headers=['币种','应返','已返','差额','状态',''];
rows=addresses.map(a=>{const t=totals.get((a.assets[0].chain==='solana'?'sol:':'evm:')+a.address);return `<tr class="addresshead"><td colspan="6"><div class="addressbar"><button class="addresscopy mono" data-copy="${esc(a.address)}" title="${esc(a.address)} · 点击复制">${esc(short(a.address))}<span>⧉</span></button><div class="addresssummary"><span>应返 <b>${usd(t.due)}</b></span><span>已返 <b>${usd(t.paid)}</b></span><span>待返 <b class="amount">${usd(t.remaining)}</b></span>${t.excess?`<span>超返 <b>${usd(t.excess)}</b></span>`:''}${t.missing?`<span class="missingquote" title="${t.missing} 项币种暂无可靠报价，未计入 U 总额">部分缺价</span>`:''}</div></div></td></tr>`+a.assets.map(g=>{const net=BigInt(g.due)-BigInt(g.paid);const amount=(raw,value)=>`<span class="quantity" title="${format(raw,g.decimals)}">${format(raw,g.decimals)}</span><span class="cellsub">${g.priced?usd(value):'—'}</span>`;return `<tr><td>${currency(g)}</td><td class="num">${amount(g.due,g.usdDue)}</td><td class="num">${amount(g.paid,g.usdPaid)}</td><td class="num ${net<0n?'warning':'amount'}">${amount(net,g.usdDue-g.usdPaid)}</td><td><span title="${g.withinTolerance?'差额小于 '+preferences.threshold+' U；':''}${complete(g.chain)?'历史已扫描':'历史扫描未完成'}">${badge(g.status)}</span></td><td><button class="secondary small" data-group="${esc(g.key)}">明细</button></td></tr>`}).join('')});

}
if(view==='assets'){const assets=new Map;for(const g of visibleGroups(groups)){const key=g.chain+':'+g.asset;if(!assets.has(key))assets.set(key,{...g,due:0n,paid:0n,remaining:0n,excess:0n,addresses:new Set});const a=assets.get(key);for(const k of ['due','paid','remaining','excess'])a[k]+=BigInt(g[k]);a.addresses.add(g.trader)}headers=['网络 / 币种','被邀请地址数','应返还合计','已返还合计','待返还合计','超返合计'];rows=[...assets.values()].map(a=>`<tr><td>${currency(a)}</td><td>${a.addresses.size}</td>${['due','paid','remaining','excess'].map(k=>`<td class="num ${k==='remaining'?'amount':''}">${format(a[k],a.decimals)}<span class="cellsub">${a.priced?usd(Number(a[k])/10**a.decimals*Number(a.price.usd)):'暂无报价'}</span></td>`).join('')}</tr>`)}

if(view==='review'){
headers=['时间 / 币种','方向','金额','对方地址','待核对原因','交易',''];
rows=pending.filter(matches).sort((a,b)=>(b.time||'').localeCompare(a.time||'')).map(r=>{const counterparty=r.direction==='in'?r.from:r.to;return `<tr><td>${currency(r)}<span class="cellsub">${r.time?esc(new Date(r.time).toLocaleString('zh-CN')):'时间待查询'}</span></td><td>${r.direction==='in'?'转入':'转出'}</td><td class="num"><span class="quantity" title="${format(r.raw,r.decimals)}">${format(r.raw,r.decimals)}</span></td><td><button class="addresscopy mono" data-copy="${esc(counterparty)}" title="${esc(counterparty)}">${esc(short(counterparty))}</button></td><td class="reviewreason">${esc(r.reviewReason||r.exclusionReason||'归属尚未确认')}</td><td><a class="mono" href="${esc(link(r))}" target="_blank" rel="noreferrer" title="${esc(r.hash)}">${esc(short(r.hash))} ↗</a></td><td><div class="actions"><button class="secondary small" data-record="${esc(r.id)}">明细</button><button class="secondary small" data-case="${esc(r.id)}">复制案例</button></div></td></tr>`});
}
if(view==='coverage'){const ids=[...new Set([...required,...state.selected])];$('tableArea').innerHTML=`<div class="coveragegrid">${ids.map(id=>{const c=chainBy(id),v=state.coverage[id],n=state.records.filter(r=>r.chain===id&&r.kind!=='ignore').length;return `<div class="coveragecard"><strong>${esc(c.name)}</strong><br><span class="pill ${complete(id)?'':c.unsupported?'red':'amber'}">${complete(id)?'历史已扫描':c.unsupported?'待接入补充数据源':v?.status==='error'?'同步未完成':v?.status==='running'?'同步中':'尚未扫描'}</span><p>${n} 笔已获取 · 原生 ${esc(c.symbol)} + 代币</p><p>${pending.filter(r=>r.chain===id).length} 笔待核对</p><p>${esc(v?.error||v?.updated&&new Date(v.updated).toLocaleString('zh-CN')||'尚未查询完整历史')}</p><button class="secondary small" data-sync-chain="${id}" ${busy?'disabled':''}>查询此链</button></div>`}).join('')}</div>`;$('rowCount').textContent=`指定范围 ${required.length} 条链；失败、未查询和未匹配记录不等于零欠款`;$('prev').disabled=$('next').disabled=true;$('pageNum').textContent='';return}
const total=rows.length,max=Math.max(1,Math.ceil(total/25));page=Math.min(page,max);$('tableArea').innerHTML=`<table><thead><tr>${headers.map((h,i)=>`<th${i>=2&&i<headers.length-1?' class="num"':''}>${h}</th>`).join('')}</tr></thead><tbody>${rows.slice((page-1)*25,page*25).join('')||`<tr><td colspan="${headers.length}" class="empty"><h3>${view==='review'?'没有匹配的待核对流水':'当前没有匹配的已识别账目'}</h3><p class="subtle">调整筛选，或先同步数据以自动识别返佣与返还。</p></td></tr>`}</tbody></table>`;$('rowCount').textContent=`${total} ${view==='ledger'?'个地址':view==='review'?'笔待核对':'项'}`;$('pageNum').textContent=`${page} / ${max}`;$('prev').disabled=page<=1;$('next').disabled=page>=max;}
function currency(r){const quote=r.priced?`1 ${r.symbol} ≈ ${usd(r.price.usd)} · ${r.price.source} · ${new Date(r.price.at).toLocaleTimeString('zh-CN')}`:'暂无可靠报价';return `<div class="currency" title="${esc((r.asset==='native'?'原生币':r.asset)+' · '+quote)}"><span class="coin">${esc(r.symbol.slice(0,1))}</span><div>${esc(r.symbol)}<span class="cellsub">${esc(chainBy(r.chain).name)}</span></div></div>`}

function settings(){$('evmWallet').value=EVM;$('solWallet').value=SOL;$('toleranceEnabled').checked=preferences.enabled;$('toleranceValue').value=preferences.threshold;drawChoices();$('settings').showModal()}
function drawChoices(){const q=$('chainSearch').value.toLowerCase();$('chainChoices').innerHTML=chains.filter(c=>(c.name+' '+c.id).toLowerCase().includes(q)).sort((a,b)=>Number(required.includes(b.id))-Number(required.includes(a.id))).map(c=>`<label><input type="checkbox" data-chain="${c.id}" ${state.selected.includes(c.id)?'checked':''} ${c.unsupported?'disabled':''}>${esc(c.name)}${c.unsupported?'（待接入）':''}</label>`).join('')}
function showRecords(ids){activeDetail=ids;const records=autoAccount(state.records).filter(r=>ids.includes(r.id));$('detailBody').innerHTML=records.map(r=>`<article class="record"><p><strong>${r.kind==='commission'?'返佣收入':r.kind==='refund'?'已返还':r.kind==='pending'?'待核对':'未计入'} · ${esc(chainBy(r.chain).name)}</strong><span class="pill" style="float:right">${format(r.raw,r.decimals)} ${esc(r.symbol)}</span></p><p class="mono">归属地址：${esc(r.trader)}</p><p class="mono">交易：${esc(r.hash)}</p><p class="mono">从：${esc(r.from)}<br>到：${esc(r.to)}</p><p class="evidence">${esc(r.reviewReason||r.exclusionReason||r.evidence)}</p>${link(r)?`<a href="${esc(link(r))}" rel="noreferrer" target="_blank">查看链上交易 ↗</a>`:''}</article>`).join('');if(!$('detail').open)$('detail').showModal()}
async function sync(onlyId,retryOnly=false){if(busy){controller.abort();return}const selected=state.selected.filter(id=>(!onlyId||id===onlyId)&&(!retryOnly||!complete(id))&&!chainBy(id).unsupported&&(id==='solana'?SOL&&keys.helius:EVM&&keys[chainBy(id).provider||'blockscout'])).sort((a,b)=>Number(['56','196'].includes(a))-Number(['56','196'].includes(b)));if(!selected.length){settings();return toast('填写对应 API Key 后点击“应用设置”，再同步历史')}busy=true;controller=new AbortController;render();let errors=0;const lanes=Object.groupBy(selected,id=>id==='solana'?'helius':chainBy(id).provider||'blockscout:'+id);try{await Promise.all(Object.values(lanes).map(async ids=>{for(const id of ids){if(controller.signal.aborted)break;const c=chainBy(id);let cov=state.coverage[id]||{streams:{},inspected:[]};if(cov.status==='complete')cov={streams:{},inspected:[]};cov.inspected||=[];cov.inspectionErrors||={};cov.status='running';cov.error='';state.coverage[id]=cov;const onPage=async(rows,p)=>{state.records=mergeRecords(state.records,rows);if(c.provider){for(const hash of [...new Set(rows.map(r=>r.hash))]){if(cov.inspected.includes(hash))continue;progress=`${c.name} · 核验新获取的交易与返佣`;render();try{const checked=await inspectorFor(c)(c,hash,keys[c.provider],routers,controller.signal);state.records=mergeRecords(state.records,checked);cov.inspected.push(hash);delete cov.inspectionErrors[hash]}catch(e){if(controller.signal.aborted)throw e;cov.inspectionErrors[hash]=e.message}save();render()}}cov.streams[p.stream]=p;state.updated=new Date().toISOString();save();render()};const onProgress=s=>{progress=s;render()};try{if(id==='solana'){await scanSolana(keys.helius,onPage,onProgress,controller.signal,cov.streams.solana||{})}else if(c.provider){for(const hash of Object.keys(cov.inspectionErrors)){if(controller.signal.aborted)throw Error('已暂停');onProgress(`${c.name} · 重试此前未能核验的交易`);try{const rows=await inspectorFor(c)(c,hash,keys[c.provider],routers,controller.signal);state.records=mergeRecords(state.records,rows);cov.inspected.push(hash);delete cov.inspectionErrors[hash]}catch(e){if(controller.signal.aborted)throw e;cov.inspectionErrors[hash]=e.message}save();render()}const scanner={nodereal:scanBSC,etherscan:scanLinea,xlayer:scanXLayer}[c.provider];await scanner(c,keys[c.provider],onPage,onProgress,controller.signal,cov.streams);const hashes=[...new Set(state.records.filter(r=>r.chain===id&&r.stream==='discovery').map(r=>r.hash))];for(let i=0;i<hashes.length;i++){const hash=hashes[i];if(cov.inspected.includes(hash))continue;onProgress(`${c.name} · 核验成功回执与内部转账 ${i+1}/${hashes.length}`);try{const rows=await inspectorFor(c)(c,hash,keys[c.provider],routers,controller.signal);state.records=mergeRecords(state.records,rows);cov.inspected.push(hash);delete cov.inspectionErrors[hash]}catch(e){if(controller.signal.aborted)throw e;cov.inspectionErrors[hash]=e.message}save();render()}}else{await scanEVM(c,keys.blockscout,routers,onPage,onProgress,controller.signal,cov.streams);const records=state.records.filter(r=>r.chain===id&&r.stream),hashes=[...new Set(records.map(r=>r.hash))];for(let i=0;i<hashes.length;i++){const hash=hashes[i];if(cov.inspected.includes(hash))continue;onProgress(`${c.name} · 核验交易与返佣事件 ${i+1}/${hashes.length}`);try{const result=await inspectEVM(c,hash,keys.blockscout,routers,records.filter(r=>r.hash===hash),controller.signal);state.records=mergeRecords(state.records,[...result.replace,...result.fees]);cov.inspected.push(hash);delete cov.inspectionErrors[hash]}catch(e){if(controller.signal.aborted)throw e;cov.inspectionErrors[hash]=e.message}save();render()}}if(Object.keys(cov.inspectionErrors).length)throw Error(`${Object.keys(cov.inspectionErrors).length} 笔交易尚未核验：${Object.values(cov.inspectionErrors)[0]}`);cov.status='complete';cov.updated=new Date().toISOString()}catch(e){cov.status='error';cov.error=controller.signal.aborted?'已暂停；下次从保存的进度继续':e.message;errors++}save();render()}}))}finally{busy=false;progress='';save();render();toast(controller.signal.aborted?'同步已暂停，进度已保存':errors?`${errors} 条链未完成，可查看“数据覆盖”后重试`:'所选网络扫描完成，账目已自动汇总')}}
function download(filename,content,type='application/json'){const blob=new Blob([content],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function backup(){download('返佣账本备份-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({...state,wallets:{evm:EVM,sol:SOL}},null,2));toast('已导出备份，未包含任何 API Key')}
function exportCsv(){if(view==='review'){const header=['网络','方向','代币','合约','金额','发送地址','接收地址','候选归属地址','交易哈希','时间','待核对原因'];const rows=pendingReview(state.records).filter(matches).map(r=>[chainBy(r.chain).name,r.direction==='in'?'转入':'转出',r.symbol,r.asset,format(r.raw,r.decimals),r.from,r.to,r.trader||r.suggestedTrader||'',r.hash,r.time,r.reviewReason||r.exclusionReason||'归属尚未确认']);const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';download('待核对流水.csv','\uFEFF'+[header,...rows].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');return}const header=['网络','被邀请地址','代币','合约或原生币','应返还','已返还','待返还','超返','状态','差额参考价值U','是否小额足额','报价时间','历史是否查完'];const rows=visibleGroups(valued()).sort((a,b)=>a.trader.localeCompare(b.trader)).map(g=>[chainBy(g.chain).name,g.trader,g.symbol,g.asset,format(g.due,g.decimals),format(g.paid,g.decimals),format(g.remaining,g.decimals),format(g.excess,g.decimals),statusText[g.status],g.priced?g.usdDifference:'暂无报价',g.withinTolerance?'是':'否',g.priced?new Date(g.price.at).toISOString():'',complete(g.chain)?'是':'否']);const safe=v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';download('返佣对账-'+new Date().toISOString().slice(0,10)+'.csv','\uFEFF'+[header,...rows].map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
$('chainFilter').innerHTML='<option value="all">所有网络</option>'+chains.filter(c=>required.includes(c.id)||state.records.some(r=>r.chain===c.id)).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');$('setupButton').onclick=settings;$('saveSettings').onclick=()=>{const evm=$('evmWallet').value.trim().toLowerCase(),sol=$('solWallet').value.trim(),threshold=$('toleranceValue').value;if(evm&&!validAddress('1',evm)||sol&&!validAddress('solana',sol))return toast('钱包地址格式不正确');if(!/^(?:0|[1-9]\d*)(?:\.\d+)?$/.test(threshold)||Number(threshold)>1000000)return toast('请填写有效差额阈值');preferences={enabled:$('toleranceEnabled').checked,threshold};localStorage.setItem('rebate-preferences-v1',JSON.stringify(preferences));if(evm!==EVM||sol!==SOL){save();configureWallets(evm,sol);try{state=JSON.parse(localStorage.getItem(walletStorage())||'null')||{version:1,records:[],selected:required,coverage:{},updated:null}}catch{state={version:1,records:[],selected:required,coverage:{},updated:null}}migrateDecoder();prices={}}const xlayer={key:$('xlayerKey').value.trim(),secret:$('xlayerSecret').value.trim(),passphrase:$('xlayerPassphrase').value.trim()};if(Object.values(xlayer).some(Boolean)&&!Object.values(xlayer).every(Boolean))return toast('X Layer 需要同时填写 API Key、Secret Key 和 Passphrase');keys={blockscout:$('blockscoutKey').value.trim(),helius:$('heliusKey').value.trim(),nodereal:$('noderealKey').value.trim(),etherscan:$('etherscanKey').value.trim(),xlayer:Object.values(xlayer).every(Boolean)?xlayer:null};try{localStorage.setItem('rebate-credentials-v1',JSON.stringify(keys))}catch{return toast('浏览器不允许保存凭证；本次仍可使用，请检查存储设置')}save();render();refreshPrices();$('settings').close();toast('凭证和网络选择已保存到本机，刷新后自动恢复')};$('chainSearch').oninput=drawChoices;$('chainChoices').onchange=e=>{const id=e.target.dataset.chain;if(!id)return;state.selected=e.target.checked?[...new Set([...state.selected,id])]:state.selected.filter(x=>x!==id)};$('selectAll').onclick=()=>{state.selected=chains.filter(c=>!/testnet/i.test(c.name)&&!c.unsupported).map(c=>c.id);drawChoices()};$('selectCommon').onclick=()=>{state.selected=[...required];drawChoices()};$('syncButton').onclick=()=>sync();$('retryButton').onclick=()=>sync(null,true);$('backupButton').onclick=backup;$('exportButton').onclick=exportCsv;$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};for(const id of ['search','chainFilter','statusFilter','assetFilter','tokenFilter','minimumUsd','minimumField'])$(id).addEventListener(id==='search'?'input':'change',()=>{page=1;render()});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{view=b.dataset.tab;page=1;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));$('statusFilter').disabled=!['ledger','assets'].includes(view);$('search').disabled=$('chainFilter').disabled=$('assetFilter').disabled=$('tokenFilter').disabled=view==='coverage';document.querySelector('.filters').hidden=view==='coverage';render()});$('tableArea').onclick=async e=>{const copy=e.target.closest('[data-copy]');if(copy){try{await navigator.clipboard.writeText(copy.dataset.copy);toast('地址已复制')}catch{toast('复制失败，请在明细中复制地址')}return}const sample=e.target.closest('[data-case]');if(sample){const r=pendingReview(state.records).find(r=>r.id===sample.dataset.case);if(!r)return;const text=['待核对案例','网络：'+chainBy(r.chain).name,'方向：'+(r.direction==='in'?'转入':'转出'),'金额：'+format(r.raw,r.decimals)+' '+r.symbol,'币种合约：'+r.asset,'发送：'+r.from,'接收：'+r.to,'交易：'+r.hash,'链接：'+link(r),'原因：'+(r.reviewReason||'归属尚未确认'),'实际用途（返佣 / 返还 / 其他）：','应归属的被邀请地址：'].join('\n');try{await navigator.clipboard.writeText(text);toast('案例已复制，可补充用途和归属地址后发给我')}catch{toast('复制失败，可打开明细复制交易哈希')}return}const sc=e.target.closest('[data-sync-chain]');if(sc){sync(sc.dataset.syncChain);return}const r=e.target.closest('[data-record]'),g=e.target.closest('[data-group]');if(r)showRecords([r.dataset.record]);if(g)showRecords(summarize(autoAccount(state.records)).find(x=>x.key===g.dataset.group).ids)};
$('clearCredentials').onclick=()=>{localStorage.removeItem('rebate-credentials-v1');keys={blockscout:'',helius:'',nodereal:'',etherscan:'',xlayer:null};for(const id of [...Object.keys(credentialFields),'xlayerKey','xlayerSecret','xlayerPassphrase'])$(id).value='';toast('已清除本浏览器保存的凭证；账目保留')};
