$('importFile').onchange=async e=>{try{if(busy)throw Error('请先暂停同步');const f=e.target.files[0];if(!f)return;if(f.size>40*1024*1024)throw Error('备份超过 40MB，请分批导入');const data=JSON.parse(await f.text());const rows=Array.isArray(data)?data:data.records;if(!Array.isArray(rows)||rows.length>100000)throw Error('需要 records 数组');rows.forEach(validateRecord);if(!EVM&&!SOL)throw Error('请先设置收款钱包');if(rows.some(r=>{const own=r.chain==='solana'?SOL:EVM;return !own||canonical(r.chain,r.from)!==own&&canonical(r.chain,r.to)!==own}))throw Error('备份包含其他钱包的记录，请先切换对应钱包');const next=mergeRecords(state.records,rows);summarize(next);state.records=next;state.coverage={};save();render();toast(`已导入 ${rows.length} 笔记录；需重新扫描以验证历史完整性`)}catch(e){toast(e.message)}finally{$('importFile').value=''}};
